func loadTermbenchSubset(path string) (*termbenchSubset, error) {
	data, err := os.ReadFile(path) // #nosec G304 -- path is operator-controlled flag
	if err != nil {
		return nil, err
	}
	var s termbenchSubset
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse subset: %w", err)
	}
	if len(s.Tasks) == 0 {
		return nil, fmt.Errorf("subset has no tasks")
	}
	return &s, nil
}

// Package termbench is the TerminalBench external-benchmark adapter.
//
// Responsibilities:
//
//  1. Parse a TerminalBench task directory (task.yaml + instruction +
//     tests/) into a typed Task.
//  2. Translate Task → an agent ServiceExecuteRequest payload (prompt,
//     work-dir, timeout). The adapter does NOT execute the task itself —
//     it returns a Plan that the caller (cmd/bench) feeds into the agent
//     service.Execute pipeline.
//  3. Capture the agent's stream of harnesses.Event into the trajectory
//     output format that TerminalBench's Harbor grader expects, namely
//     ATIF v1.4 written to <out>/logs/agent/trajectory.json. The grader
//     then runs the task's own pytest test_outputs.py against the modified
//     workspace; we do not reimplement that grading.
//
// What this package deliberately does NOT do:
//
//   - It does NOT spin up Docker containers, install Harbor, or run
//     pytest. Doing so requires the full Harbor stack (`harbor run …`)
//     and an x86_64 Docker daemon. Instead, the adapter emits the
//     artifacts Harbor expects so the upstream grader can score the run
//     unmodified. See docs/helix/02-design/external-benchmarks.md for
//     the end-to-end pipeline (agent → harness output → harbor grader).
//
//   - It does NOT reimplement TerminalBench's grading rubric. Reward
//     comes from /logs/verifier/reward.txt produced by Harbor's verifier.
//
// See SD-008 (docs/helix/02-design/solution-designs/SD-008-terminal-bench-integration.md)
// for the integration audit; this package is the Go-side companion to the
// Python adapter at scripts/benchmark/harbor_agent.py.
package termbench

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/comparison"
	"github.com/DocumentDrivenDX/fizeau/internal/safefs"
)

// cmdReport implements the 'report' subcommand.
func cmdReport(args []string) int {
	fs := flagSet("report")
	resultsDir := fs.String("results-dir", "", "Directory containing result JSON files (default: bench/results relative to cwd)")
	format := fs.String("format", "table", "Output format: table|json|markdown")
	workDir := fs.String("work-dir", "", "Agent working directory (default: cwd)")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	wd := resolveWorkDir(*workDir)

	dir := *resultsDir
	if dir == "" {
		dir = filepath.Join(wd, "bench", "results")
	}

	// Collect all bench-*.json files.
	entries, err := filepath.Glob(filepath.Join(dir, "bench-*.json"))
	if err != nil || len(entries) == 0 {
		fmt.Fprintf(os.Stderr, "%s report: no result files found in %s\n", benchCommandName(), dir)
		return 1
	}

	// Sort descending — newest first.
	sort.Sort(sort.Reverse(sort.StringSlice(entries)))

	// Load the most recent result by default.
	path := entries[0]
	data, err := safefs.ReadFile(path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s report: read %s: %v\n", benchCommandName(), path, err)
		return 1
	}

	var result comparison.BenchmarkResult
	if err := json.Unmarshal(data, &result); err != nil {
		fmt.Fprintf(os.Stderr, "%s report: parse %s: %v\n", benchCommandName(), path, err)
		return 1
	}

	switch *format {
	case "json":
		out, _ := json.MarshalIndent(result, "", "  ")
		fmt.Println(string(out))
	case "markdown":
		printMarkdownReport(&result)
	default:
		printSummaryTable(&result)
	}

	return 0
}

// printSummaryTable renders a human-readable table to stdout.
func printSummaryTable(result *comparison.BenchmarkResult) {
	fmt.Printf("Benchmark: %s  version: %s  at: %s\n\n",
		result.Suite, result.Version, result.Timestamp.Format("2006-01-02 15:04:05Z"))

	fmt.Printf("%-40s %8s %8s %12s %12s %12s\n",
		"ARM", "OK", "FAIL", "TOK", "COST_USD", "AVG_MS")
	fmt.Printf("%-40s %8s %8s %12s %12s %12s\n",
		strings.Repeat("-", 40), "-------", "-------",
		"-----------", "-----------", "-----------")
	for _, arm := range result.Summary.Arms {
		fmt.Printf("%-40s %8d %8d %12d %12.6f %12d\n",
			truncate(arm.Label, 40),
			arm.Completed, arm.Failed,
			arm.TotalTokens,
			arm.TotalCostUSD,
			arm.AvgDurationMS,
		)
	}
	fmt.Printf("\nTotal prompts: %d\n", result.Summary.TotalPrompts)

	printCostCapSkips(result)
	printParityMatrix(result)
}

// printCostCapSkips lists any tasks that were skipped due to cost cap.
func printCostCapSkips(result *comparison.BenchmarkResult) {
	type skip struct {
		prompt string
		arm    string
	}
	var skips []skip
	for _, cmp := range result.Comparisons {
		for _, arm := range cmp.Arms {
			if arm.Error == CostCapSkipReason {
				skips = append(skips, skip{prompt: cmp.ID, arm: arm.Harness})
			}
		}
	}
	if len(skips) == 0 {
		return
	}
	fmt.Printf("\n--- Cost cap skips (%d) ---\n", len(skips))
	for _, s := range skips {
		fmt.Printf("  skipped: prompt=%s  arm=%s\n", s.prompt, s.arm)
	}
}

// printParityMatrix prints a per-task parity comparison between all arm pairs.
func printParityMatrix(result *comparison.BenchmarkResult) {
	if len(result.Arms) < 2 || len(result.Comparisons) == 0 {
		return
	}

	// Build arm labels slice.
	labels := make([]string, len(result.Arms))
	for i, a := range result.Arms {
		labels[i] = a.Label
	}

	fmt.Printf("\n--- Parity matrix (tool-call sequence equality / output similarity) ---\n")
	fmt.Printf("%-20s  %-30s  %-30s  %8s  %10s\n", "PROMPT", "ARM_A", "ARM_B", "TC_EQUAL", "OUT_SIM")
	fmt.Printf("%-20s  %-30s  %-30s  %8s  %10s\n",
		strings.Repeat("-", 20), strings.Repeat("-", 30), strings.Repeat("-", 30), "--------", "----------")

	for _, cmp := range result.Comparisons {
		cells := BuildParityMatrix(cmp, labels)
		for _, cell := range cells {
			eq := "NO"
			if cell.ToolSeqEqual {
				eq = "YES"
			}
			fmt.Printf("%-20s  %-30s  %-30s  %8s  %10.3f\n",
				truncate(cmp.ID, 20),
				truncate(cell.ArmA, 30),
				truncate(cell.ArmB, 30),
				eq,
				cell.OutputSimilarity,
			)
		}
	}

	// Determinism notice.
	fmt.Printf("\nNOTE: %s\n", DeterministicSamplingNotice)
	fmt.Printf("      Parity results for non-deterministic harnesses are advisory only.\n")
}

// printMarkdownReport renders a GitHub-flavored Markdown report.
func printMarkdownReport(result *comparison.BenchmarkResult) {
	fmt.Printf("## Benchmark: %s\n\n", result.Suite)
	fmt.Printf("- **Version**: %s\n", result.Version)
	fmt.Printf("- **Run at**: %s\n", result.Timestamp.Format("2006-01-02 15:04:05Z"))
	fmt.Printf("- **Prompts**: %d\n\n", result.Summary.TotalPrompts)

	fmt.Println("| Arm | OK | Fail | Tokens | Cost USD | Avg ms |")
	fmt.Println("|-----|---:|---:|---:|---:|---:|")
	for _, arm := range result.Summary.Arms {
		fmt.Printf("| %s | %d | %d | %d | %.6f | %d |\n",
			arm.Label, arm.Completed, arm.Failed,
			arm.TotalTokens, arm.TotalCostUSD, arm.AvgDurationMS)
	}

	// Cost cap skips section.
	var skipLines []string
	for _, cmp := range result.Comparisons {
		for _, arm := range cmp.Arms {
			if arm.Error == CostCapSkipReason {
				skipLines = append(skipLines, fmt.Sprintf("- prompt `%s`, arm `%s`", cmp.ID, arm.Harness))
			}
		}
	}
	if len(skipLines) > 0 {
		fmt.Printf("\n### Cost cap skips\n\n")
		for _, l := range skipLines {
			fmt.Println(l)
		}
	}

	// Parity matrix section.
	if len(result.Arms) >= 2 && len(result.Comparisons) > 0 {
		labels := make([]string, len(result.Arms))
		for i, a := range result.Arms {
			labels[i] = a.Label
		}

		fmt.Printf("\n### Parity matrix\n\n")
		fmt.Println("| Prompt | Arm A | Arm B | TC Equal | Out Sim |")
		fmt.Println("|--------|-------|-------|:--------:|--------:|")
		for _, cmp := range result.Comparisons {
			for _, cell := range BuildParityMatrix(cmp, labels) {
				eq := "no"
				if cell.ToolSeqEqual {
					eq = "**yes**"
				}
				fmt.Printf("| %s | %s | %s | %s | %.3f |\n",
					cmp.ID, cell.ArmA, cell.ArmB, eq, cell.OutputSimilarity)
			}
		}

		fmt.Printf("\n> **Note**: %s  \n", DeterministicSamplingNotice)
		fmt.Printf("> Parity results for non-deterministic harnesses are advisory only.\n")
	}
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n-1] + "…"
}

	args = append(args,
		"--model", opts.profile.Provider.Model,
		"--jobs-dir", opts.jobsDir,
		"--job-name", opts.jobName,
	)
	if truthyEnv("HARBOR_FORCE_BUILD") {
		args = append(args, "--force-build")
	}
	if multiplier := strings.TrimSpace(os.Getenv("HARBOR_AGENT_TIMEOUT_MULTIPLIER")); multiplier != "" {
		args = append(args, "--agent-timeout-multiplier", multiplier)
	}
	if apiKeyVal != "" {
		args = append(args, "--ae", apiKeyEnv+"="+apiKeyVal)
	}
	// Pass provider config so Harbor agents can configure the model endpoint.
	args = append(args,
		"--ae", "FIZEAU_BASE_URL="+opts.profile.Provider.BaseURL,
		"--ae", "FIZEAU_MODEL="+opts.profile.Provider.Model,
		"--ae", "FIZEAU_PROVIDER="+fizeauProviderEnv(opts.profile),
	)
	if apiKeyVal != "" {
		args = append(args, "--ae", "FIZEAU_API_KEY="+apiKeyVal)
	}
	// Forward sampling params so fiz reads them via FIZEAU_* env overrides.
	for _, kv := range samplingEnvPairs(opts.profile) {
		args = append(args, "--ae", kv)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 35*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, opts.harborBin, args...) // #nosec G204 G702 -- harborBin is a validated binary path from config
	// Add repo root to PYTHONPATH so harbor_adapters modules resolve.
	env := os.Environ()
	pythonPath := opts.repoRoot
	for i, e := range env {
		if strings.HasPrefix(e, "PYTHONPATH=") {
			pythonPath = opts.repoRoot + string(os.PathListSeparator) + e[len("PYTHONPATH="):]
			env[i] = "PYTHONPATH=" + pythonPath
			pythonPath = ""
			break
		}
	}
	if pythonPath != "" {
		env = append(env, "PYTHONPATH="+pythonPath)
	}
	cmd.Env = env
	cmd.Dir = opts.repoRoot

	var combined bytes.Buffer
	cmd.Stdout = &combined
	cmd.Stderr = &combined
	runErr := cmd.Run()
	wall := time.Since(started).Seconds()

	exitCode := 0
	if runErr != nil {
		var ee *exec.ExitError
		if errors.As(runErr, &ee) {
			exitCode = ee.ExitCode()
		} else {
			return harborRunResult{}, runErr
		}
	}

	// Find reward.txt written by the Harbor verifier.
	var reward *int
	jobOutDir := filepath.Join(opts.jobsDir, opts.jobName)
	entries, _ := os.ReadDir(jobOutDir)
	for _, e := range entries {
		rewardFile := filepath.Join(jobOutDir, e.Name(), "verifier", "reward.txt")
		data, err := os.ReadFile(rewardFile) // #nosec G304 -- rewardFile is under runner-owned output dir
		if err == nil {
			val, err := strconv.Atoi(strings.TrimSpace(string(data)))
			if err == nil {
				reward = &val
			}
			break
		}
	}

	errText := ""
	if exitCode != 0 || reward == nil {
		errText = strings.TrimSpace(combined.String())
		if len(errText) > 2000 {
			errText = errText[:2000]
		}
	}
	return harborRunResult{
		reward:      reward,
		exitCode:    exitCode,
		wallSeconds: wall,
		errText:     errText,
	}, nil
}

func runMatrixAdapter(repoRoot, module string, prof *profile.Profile, prompt, taskID, workDir string) (matrixAdapterResult, error) {
	profileJSON, err := json.Marshal(adapterProfileMapping(prof))
	if err != nil {
		return matrixAdapterResult{}, err
	}
	script := `
import importlib, json, os, subprocess, sys, time
from scripts.benchmark.harness_adapters.base import BenchmarkProfile

module = importlib.import_module(sys.argv[1])
profile_raw = json.loads(sys.argv[2])
prompt = sys.argv[3]
task_id = sys.argv[4]
workdir = sys.argv[5]
agent = module.Agent()
profile = BenchmarkProfile.from_mapping(profile_raw)
apply = agent.apply_profile(profile)
command = agent.command(profile, prompt, workdir)
env = os.environ.copy()
env.update(getattr(apply, "env", {}) or {})
env.update(getattr(command, "env", {}) or {})
started = time.time()
stdout = ""
stderr = ""
exit_code = 0
argv = list(getattr(command, "argv", []) or [])
if argv:
    proc = subprocess.run(
        argv,
        input=getattr(command, "stdin", None),
        text=True,
        capture_output=True,
        cwd=getattr(command, "cwd", None) or workdir,
        env=env,
        timeout=1800,
    )
    stdout = proc.stdout
    stderr = proc.stderr
    exit_code = proc.returncode
duration_ms = int((time.time() - started) * 1000)
stream = task_id + "\n" + stdout + "\n" + stderr
telemetry = agent.parse_telemetry(stream)
def spec_to_dict(spec):
    return {
        "argv": list(getattr(spec, "argv", []) or []),
        "env": dict(getattr(spec, "env", {}) or {}),
        "notes": list(getattr(spec, "notes", []) or []),
        "cwd": getattr(spec, "cwd", None) or "",
    }
print(json.dumps({
    "telemetry": telemetry,
    "apply": spec_to_dict(apply),
    "command": spec_to_dict(command),
    "stdout": stdout,
    "stderr": stderr,
    "exit_code": exit_code,
    "duration_ms": duration_ms,
}, sort_keys=True))
`
	ctx, cancel := context.WithTimeout(context.Background(), 31*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, "python3", "-c", script, module, string(profileJSON), prompt, taskID, workDir) // #nosec G204 -- python3 is a fixed system binary
	cmd.Dir = repoRoot
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if ctx.Err() != nil {
		return matrixAdapterResult{}, ctx.Err()
	}
	if err != nil {
		if stderr.Len() > 0 {
			return matrixAdapterResult{}, fmt.Errorf("%w: %s", err, strings.TrimSpace(stderr.String()))
		}
		return matrixAdapterResult{}, err
	}
	var result matrixAdapterResult
	if err := json.Unmarshal(out, &result); err != nil {
		return matrixAdapterResult{}, fmt.Errorf("parse adapter result: %w", err)
	}
	return result, nil
}

func selectMatrixProfiles(workDir string, ids []string) ([]*profile.Profile, error) {
	profilesDir := filepath.Join(workDir, defaultProfilesDir)
	loaded, err := profile.LoadDir(profilesDir)
	if err != nil {
		return nil, err
	}
	byID := map[string]*profile.Profile{}
	for _, p := range loaded {
		byID[p.ID] = p
	}
	selected := make([]*profile.Profile, 0, len(ids))
	for _, id := range ids {
		p, ok := byID[id]
		if !ok {
			return nil, fmt.Errorf("profile %q not found under %s", id, profilesDir)
		}
		selected = append(selected, p)
	}
	return selected, nil
}

func splitCSV(raw string) []string {
	var out []string
	for _, part := range strings.Split(raw, ",") {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

func matrixTupleDir(outDir, harness, profileID string, rep int, taskID string) string {
	return filepath.Join(outDir, "cells", safeMatrixSegment(harness), safeMatrixSegment(profileID), fmt.Sprintf("rep-%03d", rep), safeMatrixSegment(taskID))
}

func safeMatrixSegment(s string) string {
	replacer := strings.NewReplacer("/", "_", "\\", "_", ":", "_", " ", "_")
	return replacer.Replace(s)
}

func matrixAdapterModule(harness string) string {
	return "scripts.benchmark.harness_adapters." + strings.TrimSuffix(moduleFileName(harness), ".py")
}

func moduleFileName(harness string) string {
	return strings.ReplaceAll(harness, "-", "_") + ".py"
}

func matrixPrompt(task termbenchSubsetEntry) string {
	return fmt.Sprintf("Complete TerminalBench task %s.", task.ID)
}

func matrixRunKey(r matrixRunReport) string {
	return fmt.Sprintf("%s\x00%s\x00%06d\x00%s", r.Harness, r.ProfileID, r.Rep, r.TaskID)
}

func shouldSkipMatrixReport(report matrixRunReport, resume, retryBudgetHalted bool) bool {
	if !resume {
		return false
	}
	if retryBudgetHalted && report.FinalStatus == "budget_halted" {
		return false
	}

	}
	if classifyMatrixInvalid(report) != "" {
		return true
	}
	switch report.FinalStatus {
	case "graded_pass", "graded_fail", "install_fail_permanent", "budget_halted":
		return true
	default:
		return false
	}
}

func loadExistingMatrixReport(path string) (matrixRunReport, bool, error) {
	data, err := os.ReadFile(path) // #nosec G304 -- path is a runner-owned report path
	if errors.Is(err, os.ErrNotExist) {
		return matrixRunReport{}, false, nil
	}
	if err != nil {
		return matrixRunReport{}, false, fmt.Errorf("read existing report %s: %w", path, err)
	}
	var report matrixRunReport
	if err := json.Unmarshal(data, &report); err != nil {
		return matrixRunReport{}, false, fmt.Errorf("parse existing report %s: %w", path, err)
	}
	return report, true, nil
}

func acquireMatrixLock(path string) (func(), error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return nil, err
	}
	lock := matrixLock{PID: os.Getpid(), StartedAt: time.Now().UTC()}
	raw, _ := json.Marshal(lock)
	for attempts := 0; attempts < 2; attempts++ {
		f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600) // #nosec G304 -- path is the matrix lock file path
		if err == nil {
			if _, werr := f.Write(raw); werr != nil {
				_ = f.Close()
				_ = os.Remove(path)
				return nil, werr
			}
			if err := f.Close(); err != nil {
				_ = os.Remove(path)
				return nil, err
			}
			return func() { _ = os.Remove(path) }, nil
		}
		if !errors.Is(err, os.ErrExist) {
			return nil, err
		}
		existing, readErr := readMatrixLock(path)
		if readErr == nil && !processAlive(existing.PID) {
			if removeErr := os.Remove(path); removeErr != nil && !errors.Is(removeErr, os.ErrNotExist) {
				return nil, fmt.Errorf("remove stale lock %s: %w", path, removeErr)
			}
			continue
		}
		pid := "unknown"
		if readErr == nil && existing.PID > 0 {
			pid = strconv.Itoa(existing.PID)
		}
		return nil, fmt.Errorf("matrix tuple locked by pid %s: %s", pid, path)
	}
	return nil, fmt.Errorf("could not acquire matrix tuple lock: %s", path)
}

func readMatrixLock(path string) (matrixLock, error) {
	data, err := os.ReadFile(path) // #nosec G304 -- path is a runner-owned lock path
	if err != nil {
		return matrixLock{}, err
	}
	var lock matrixLock
	if err := json.Unmarshal(data, &lock); err != nil {
		return matrixLock{}, err
	}
	return lock, nil
}

func processAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	err := syscall.Kill(pid, 0)
	return err == nil || errors.Is(err, syscall.EPERM)
}

func writeJSONAtomic(path string, value any) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return err
	}
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

func adapterProfileMapping(p *profile.Profile) map[string]any {
	return map[string]any{
		"id": p.ID,
		"provider": map[string]any{
			"type":        string(p.Provider.Type),
			"model":       p.Provider.Model,
			"base_url":    p.Provider.BaseURL,
			"api_key_env": p.Provider.APIKeyEnv,
		},
		"sampling": samplingUsedFromProfile(p),
		"limits": map[string]any{
			"max_output_tokens": p.Limits.MaxOutputTokens,
			"context_tokens":    p.Limits.ContextTokens,
		},
	}
}

func applyTelemetry(report *matrixRunReport, telemetry map[string]any) {
	report.ProcessOutcome = stringField(telemetry, "process_outcome")
	report.GradingOutcome = stringField(telemetry, "grading_outcome")
	report.Retriable = boolField(telemetry, "retriable")
	report.Reward = intPointerField(telemetry, "reward")
	report.Turns = intPointerField(telemetry, "turns")
	report.ToolCalls = intPointerField(telemetry, "tool_calls")
	report.ToolCallErrors = intPointerField(telemetry, "tool_call_errors")
	report.InputTokens = intPointerField(telemetry, "input_tokens")
	report.OutputTokens = intPointerField(telemetry, "output_tokens")
	report.CachedInputTokens = intPointerField(telemetry, "cached_input_tokens")
	report.RetriedInputTokens = intPointerField(telemetry, "retried_input_tokens")
	report.WallSeconds = floatPointerField(telemetry, "wall_seconds")
}

func deriveMatrixFinalStatus(processOutcome, gradingOutcome string, reward *int, retriable bool) string {
	switch processOutcome {
	case "budget_halted":
		return "budget_halted"
	case "install_failed":
		if retriable {
			return "install_fail_transient"
		}
		return "install_fail_permanent"
	case "auth_fail", "provider_refusal", "malformed_command", "verifier_fail":
		return processOutcome
	}
	if gradingOutcome == "graded" && reward != nil {
		if *reward == 1 {
			return "graded_pass"
		}
		return "graded_fail"
	}
	if processOutcome == "completed" && gradingOutcome == "ungraded" {
		return "ran"
	}
	if processOutcome != "" {
		return processOutcome
	}
	return "harness_crash"
}

func matrixCostUSD(p *profile.Profile, report matrixRunReport) float64 {
	input := intValue(report.InputTokens)
	output := intValue(report.OutputTokens)
	cached := intValue(report.CachedInputTokens)
	return (float64(input)*p.Pricing.InputUSDPerMTok +
		float64(output)*p.Pricing.OutputUSDPerMTok +
		float64(cached)*p.Pricing.CachedInputUSDPerMTok) / 1_000_000
}

func summarizeMatrixCells(runs []matrixRunReport) []matrixCell {
	type acc struct {
		cell          matrixCell
		rewards       []float64
		invalidCounts map[string]int
		cost          float64
		inputTokens   int
		outputTokens  int
		cachedTokens  int
		retriedTokens int
	}
	byKey := map[string]*acc{}
	for _, run := range runs {
		key := run.Harness + "\x00" + run.ProfileID
		a := byKey[key]
		if a == nil {
			a = &acc{cell: matrixCell{Harness: run.Harness, ProfileID: run.ProfileID}}
			byKey[key] = a
		}
		a.cell.NRuns++
		if invalidClass := classifyMatrixInvalid(run); invalidClass != "" {
			a.cell.NInvalid++
			if a.invalidCounts == nil {
				a.invalidCounts = map[string]int{}
			}
			a.invalidCounts[invalidClass]++
		} else {
			a.cell.NValid++
			if run.Reward != nil {
				a.cell.NReported++
				a.rewards = append(a.rewards, float64(*run.Reward))
			}
		}
		a.cost += run.CostUSD
		a.inputTokens += intValue(run.InputTokens)
		a.outputTokens += intValue(run.OutputTokens)
		a.cachedTokens += intValue(run.CachedInputTokens)
		a.retriedTokens += intValue(run.RetriedInputTokens)
	}
	cells := make([]matrixCell, 0, len(byKey))
	for _, a := range byKey {
		a.cell.CostUSD = a.cost
		a.cell.InputTokens = a.inputTokens
		a.cell.OutputTokens = a.outputTokens
		a.cell.CachedTokens = a.cachedTokens
		a.cell.RetriedTokens = a.retriedTokens
		a.cell.InvalidCounts = a.invalidCounts
		if len(a.rewards) > 0 {
			mean := mean(a.rewards)
			sd := sampleSD(a.rewards, mean)
			a.cell.MeanReward = &mean
			a.cell.SDReward = &sd
		}
		cells = append(cells, a.cell)
	}
	sort.Slice(cells, func(i, j int) bool {
		if cells[i].Harness == cells[j].Harness {
			return cells[i].ProfileID < cells[j].ProfileID
		}
		return cells[i].Harness < cells[j].Harness
	})
	return cells
}

func mean(values []float64) float64 {
	var sum float64
	for _, v := range values {
		sum += v
	}
	return sum / float64(len(values))
}

func sampleSD(values []float64, mean float64) float64 {
	if len(values) < 2 {
		return 0
	}
	var sum float64
	for _, v := range values {
		d := v - mean
		sum += d * d
	}
	return math.Sqrt(sum / float64(len(values)-1))
}

func intValue(v *int) int {
	if v == nil {
		return 0
	}
	return *v
}

func stringField(m map[string]any, key string) string {
	if v, ok := m[key].(string); ok {
		return v
	}
	return ""
}

func boolField(m map[string]any, key string) bool {
	if v, ok := m[key].(bool); ok {
		return v
	}
	return false
}

func intPointerField(m map[string]any, key string) *int {
	v, ok := m[key]
	if !ok || v == nil {
		return nil
	}
	switch n := v.(type) {

	switch n := v.(type) {
	case float64:
		out := int(n)
		return &out
	case int:
		out := n
		return &out
	default:
		return nil
	}
}

func floatPointerField(m map[string]any, key string) *float64 {
	v, ok := m[key]
	if !ok || v == nil {
		return nil
	}
	switch n := v.(type) {
	case float64:
		out := n
		return &out
	case int:
		out := float64(n)
		return &out
	default:
		return nil
	}
}

func profilePricingSource(p *profile.Profile) string {
	data, err := os.ReadFile(p.Path) // #nosec G304 -- profile path has already been loaded and validated
	if err != nil {
		return p.Path
	}
	sum := sha256.Sum256(data)
	return p.Path + "#sha256=" + hex.EncodeToString(sum[:])
}

