	}
	rel := filepath.Join(append([]string{runDir}, parts...)...)
	abs := resolveBenchmarkPath("", matrixRoot, rel)
	if abs == "" {
		return "", ""
	}
	if _, err := os.Stat(abs); err != nil {
		return "", ""
	}
	return filepath.ToSlash(rel), sha256File(abs)
}

